head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textbox > M > setDisplayFormatter]<br/>컴포넌트의 displayFormatter 속성을 설정합니다.",
    "validation" : [
        "formatter(필수) 파라미터로 formatter 내부 텍스트의 포맷을 변환할 사용자 정의 함수를 설정합니다.",
        "localeRef 속성으로 클라이언트 다국어가 적용되어 있으면 displayFormatter 속성은 무시되어야 합니다.",        
        "사용자 정의 함수의 파라미터로 escape 속성에 의해 이스케이프 처리된 내부 텍스트가 전달되어야 합니다.",        
        "사용자 정의 함수의 반환값이 새로운 내부 텍스트로 적용되어야 합니다.",        
        "displayFormatter 속성이 설정되면 displayFormat 속성은 무시되어야 합니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);    
};



// 사용자 정의 함수
scwin.fn_dpformat = function(val) {
    return val.toUpperCase();
};



