scwin.btn_getText_onclick = function (e) {   
    for(var i =1; i < 4; i ++) {
        wf_body_bottom.getObj("scwin").setReturnValue(eval('target'+i+'.render.textContent'));      
    }    
};



scwin.btn_setDisplayFormatter_onclick = function (e) {
    target1.setDisplayFormatter(par_formatter.getValue());    
    target2.setDisplayFormatter(par_formatter.getValue());    
    target3.setDisplayFormatter(par_formatter.getValue());    
};
